#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, m;
    if (!(std::cin >> n >> m)) return 0;
    std::vector<std::string> chart(n, std::string(n, 'D'));
    for (int i = 0; i < n; ++i) {
        std::string row;
        std::cin >> row;
        for (int j = 0; j <= i; ++j) {
            chart[i][j] = row[j];
            chart[j][i] = (row[j] == 'W' ? 'L' : row[j] == 'L' ? 'W' : 'D');
        }
    }
    while (m--) {
        int a, b;
        std::cin >> a >> b;
        --a; --b;
        long long common = 0;
        for (int x = 0; x < n; ++x)
            if (chart[x][a] == 'W' && chart[x][b] == 'W') ++common;
        std::cout << 1LL*n*n-(n-common)*(n-common) << '\n';
    }
}
