    int t;
    std::cin >> t;
    while (t--) {
        int n;
        std::cin >> n;
        std::vector<int> count(n+1);
        int peak = 0;
        for (int i = 0; i < n; ++i) {
            int h;
            std::cin >> h;
            ++count[h];
            if (h > peak) peak = h;
        }
        int answer = 1;
        for (int h = 1; h < peak; ++h)
            if (count[h] >= 2) answer += 2;
        std::cout << answer << '\n';
    }
}
