#include <algorithm>
#include <array>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, q;
    if (!(std::cin >> n >> q)) return 0;
    std::string s;
    std::cin >> s;
    std::array<std::vector<int>,26> positions;
    for (int i = 0; i < n; ++i) positions[s[i]-'a'].push_back(i);
    std::vector<int> next_change(n,n);
    for (int i = n-2; i >= 0; --i)
        next_change[i] = (s[i] != s[i+1] ? i+1 : next_change[i+1]);
    while (q--) {
        int left, right;
        std::cin >> left >> right;
        --left; --right;
        long long answer = -1;
        for (int c = 0; c < 26; ++c) {
            const auto& p = positions[c];
            if (p.empty()) continue;
            int first = (s[left]-'a' == c ? next_change[left] : left);
            if (first > right) continue;
            auto after = std::upper_bound(p.begin(),p.end(),right);
            if (after == p.begin()) continue;
            int last = *(after-1);
            if (last-first < 2) continue;
            int target = (first+last+1)/2;
            auto near = std::lower_bound(p.begin(),p.end(),target);
            auto consider = [&](int middle) {
                if (first < middle && middle < last)
                    answer = std::max(answer,1LL*(middle-first)*(last-middle));
            };
            if (near != p.end()) consider(*near);
            if (near != p.begin()) consider(*(near-1));
        }
        std::cout << answer << '\n';
    }
}
